//! A window manager written for river, on Solium (`crate::river`): a real
//! river client on the other end of a socket, which binds the globals,
//! tiles every window into a column of the output in its manage and render
//! sequences, binds a key, and focuses the last window.

use super::*;

/// The client half of river's protocols, generated from the interfaces the
/// compositor is built from.
mod protocol {
    #![allow(missing_docs, clippy::all, reason = "generated by wayland-scanner")]

    pub(super) mod window_management {
        use wayland_client;
        use wayland_client::protocol::*;

        pub(crate) mod __interfaces {
            use wayland_client::protocol::__interfaces::*;
            wayland_scanner::generate_interfaces!("protocols/river-window-management-v1.xml");
        }
        use self::__interfaces::*;

        wayland_scanner::generate_client_code!("protocols/river-window-management-v1.xml");
    }

    pub(super) mod xkb_bindings {
        use wayland_client;

        pub(crate) use super::window_management::river_seat_v1;

        pub(crate) mod __interfaces {
            use super::super::window_management::__interfaces::*;
            wayland_scanner::generate_interfaces!("protocols/river-xkb-bindings-v1.xml");
        }
        use self::__interfaces::*;

        wayland_scanner::generate_client_code!("protocols/river-xkb-bindings-v1.xml");
    }
}

use protocol::window_management::{
    river_node_v1::RiverNodeV1,
    river_output_v1::{self, RiverOutputV1},
    river_seat_v1::{self, RiverSeatV1},
    river_window_manager_v1::{self, RiverWindowManagerV1},
    river_window_v1::{self, RiverWindowV1},
};
use protocol::xkb_bindings::{
    river_xkb_binding_v1::{self, RiverXkbBindingV1},
    river_xkb_bindings_v1::RiverXkbBindingsV1,
};

/// A window as the test's window manager knows it.
#[derive(Debug)]
struct Tile {
    window: RiverWindowV1,
    node: RiverNodeV1,
    size: Option<(i32, i32)>,
    closed: bool,
}

/// The test's window manager: tinyrwm's shape, in columns.
#[derive(Debug, Default)]
struct RiverWm {
    manager: Option<RiverWindowManagerV1>,
    bindings: Option<RiverXkbBindingsV1>,
    seat: Option<RiverSeatV1>,
    output: Option<(i32, i32, i32, i32)>,
    tiles: Vec<Tile>,
    key: Option<RiverXkbBindingV1>,
    pressed: u32,
    unavailable: bool,
    manages: u32,
    renders: u32,
    synced: bool,
    /// Every window at a size of its own, each 100 pixels further along,
    /// as a stacking window manager places them (tinyrwm's way).
    free: bool,
    /// Close the first window in the next manage sequence.
    close_first: bool,
}

impl RiverWm {
    fn manage(&mut self) {
        self.tiles.retain(|tile| !tile.closed);
        if std::mem::take(&mut self.close_first)
            && let Some(first) = self.tiles.first()
        {
            first.window.close();
        }
        let Some((_, _, width, height)) = self.output else {
            return;
        };
        let count = i32::try_from(self.tiles.len()).unwrap_or(1).max(1);
        for tile in &self.tiles {
            if self.free {
                tile.window.propose_dimensions(0, 0);
            } else {
                tile.window.propose_dimensions(width / count, height);
            }
        }
        if let (Some(seat), Some(last)) = (&self.seat, self.tiles.last()) {
            seat.focus_window(&last.window);
        }
    }

    fn render(&self) {
        let Some((x, y, width, _)) = self.output else {
            return;
        };
        let count = i32::try_from(self.tiles.len()).unwrap_or(1).max(1);
        for (column, tile) in (0..).zip(&self.tiles) {
            if self.free {
                tile.node.set_position(x + 100 * (column + 1), y + 50);
            } else {
                tile.node.set_position(x + width / count * column, y);
            }
        }
    }
}

impl RiverWm {
    /// Ask for a manage sequence, as a window manager does when something
    /// of its own changed.
    fn manage_dirty(&self) {
        if let Some(manager) = &self.manager {
            manager.manage_dirty();
        }
    }
}

impl Dispatch<wl_registry::WlRegistry, ()> for RiverWm {
    fn event(
        state: &mut Self,
        registry: &wl_registry::WlRegistry,
        event: wl_registry::Event,
        (): &(),
        _conn: &Connection,
        qh: &QueueHandle<Self>,
    ) {
        if let wl_registry::Event::Global {
            name, interface, ..
        } = event
        {
            match interface.as_str() {
                "river_window_manager_v1" => {
                    state.manager =
                        Some(registry.bind::<RiverWindowManagerV1, _, _>(name, 4, qh, ()));
                }
                "river_xkb_bindings_v1" => {
                    state.bindings =
                        Some(registry.bind::<RiverXkbBindingsV1, _, _>(name, 1, qh, ()));
                }
                _ => {}
            }
        }
    }
}

impl Dispatch<RiverWindowManagerV1, ()> for RiverWm {
    fn event(
        state: &mut Self,
        manager: &RiverWindowManagerV1,
        event: river_window_manager_v1::Event,
        (): &(),
        _conn: &Connection,
        qh: &QueueHandle<Self>,
    ) {
        use river_window_manager_v1::Event;
        match event {
            Event::Unavailable => state.unavailable = true,
            Event::Window { id } => {
                let node = id.get_node(qh, ());
                state.tiles.push(Tile {
                    window: id,
                    node,
                    size: None,
                    closed: false,
                });
            }
            Event::Seat { id } => {
                if let (Some(bindings), None) = (&state.bindings, &state.key) {
                    // super+t.
                    let key =
                        bindings.get_xkb_binding(&id, 0x74, river_seat_v1::Modifiers::Mod4, qh, ());
                    key.enable();
                    state.key = Some(key);
                }
                state.seat = Some(id);
            }
            Event::ManageStart => {
                state.manages += 1;
                state.manage();
                manager.manage_finish();
            }
            Event::RenderStart => {
                state.renders += 1;
                state.render();
                manager.render_finish();
            }
            _ => {}
        }
    }

    wayland_client::event_created_child!(RiverWm, RiverWindowManagerV1, [
        river_window_manager_v1::EVT_WINDOW_OPCODE => (RiverWindowV1, ()),
        river_window_manager_v1::EVT_OUTPUT_OPCODE => (RiverOutputV1, ()),
        river_window_manager_v1::EVT_SEAT_OPCODE => (RiverSeatV1, ()),
    ]);
}

impl Dispatch<RiverWindowV1, ()> for RiverWm {
    fn event(
        state: &mut Self,
        window: &RiverWindowV1,
        event: river_window_v1::Event,
        (): &(),
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
    ) {
        let Some(tile) = state.tiles.iter_mut().find(|tile| tile.window == *window) else {
            return;
        };
        match event {
            river_window_v1::Event::Dimensions { width, height } => {
                tile.size = Some((width, height));
            }
            river_window_v1::Event::Closed => {
                tile.closed = true;
                window.destroy();
            }
            _ => {}
        }
    }
}

impl Dispatch<RiverOutputV1, ()> for RiverWm {
    fn event(
        state: &mut Self,
        _output: &RiverOutputV1,
        event: river_output_v1::Event,
        (): &(),
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
    ) {
        let (mut x, mut y, mut width, mut height) = state.output.unwrap_or_default();
        match event {
            river_output_v1::Event::Position { x: at_x, y: at_y } => (x, y) = (at_x, at_y),
            river_output_v1::Event::Dimensions {
                width: w,
                height: h,
            } => (width, height) = (w, h),
            _ => return,
        }
        state.output = Some((x, y, width, height));
    }
}

impl Dispatch<RiverXkbBindingV1, ()> for RiverWm {
    fn event(
        state: &mut Self,
        _binding: &RiverXkbBindingV1,
        event: river_xkb_binding_v1::Event,
        (): &(),
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
    ) {
        if let river_xkb_binding_v1::Event::Pressed = event {
            state.pressed += 1;
        }
    }
}

impl Dispatch<wl_callback::WlCallback, ()> for RiverWm {
    fn event(
        state: &mut Self,
        _callback: &wl_callback::WlCallback,
        _event: wl_callback::Event,
        (): &(),
        _conn: &Connection,
        _qh: &QueueHandle<Self>,
    ) {
        state.synced = true;
    }
}

wayland_client::delegate_noop!(RiverWm: ignore RiverSeatV1);
wayland_client::delegate_noop!(RiverWm: ignore RiverNodeV1);
wayland_client::delegate_noop!(RiverWm: ignore RiverXkbBindingsV1);

/// The river window manager connected to the compositor, with its queue.
struct Connected {
    conn: Connection,
    queue: wayland_client::EventQueue<RiverWm>,
    wm: RiverWm,
}

fn connect_river(display: &mut Display<Solium>, state: &mut Solium) -> Connected {
    let (server_side, client_side) = UnixStream::pair().expect("a socketpair");
    display
        .handle()
        .insert_client(server_side, std::sync::Arc::new(ClientState::default()))
        .expect("inserting the river window manager");
    let conn = Connection::from_socket(client_side).expect("wrapping its socket");
    let mut queue = conn.new_event_queue::<RiverWm>();
    let qh = queue.handle();
    let mut wm = RiverWm::default();
    conn.display().get_registry(&qh, ());
    conn.flush().expect("flushing get_registry");
    display.dispatch_clients(state).expect("dispatching");
    display.flush_clients().expect("flushing");
    queue.blocking_dispatch(&mut wm).expect("the registry");
    Connected { conn, queue, wm }
}

/// Let the compositor and the river window manager talk until both have
/// nothing left to say: each round trip, the window manager's requests are
/// dispatched, what the bridge submitted is applied, and the events that
/// follow are read.
fn settle(display: &mut Display<Solium>, state: &mut Solium, river: &mut Connected) {
    for _ in 0..8 {
        let qh = river.queue.handle();
        river.wm.synced = false;
        river.conn.display().sync(&qh, ());
        river.conn.flush().expect("flushing the window manager");
        display.dispatch_clients(state).expect("dispatching it");
        crate::wm::settle(state);
        display.flush_clients().expect("flushing to it");
        while !river.wm.synced {
            river
                .queue
                .blocking_dispatch(&mut river.wm)
                .expect("reading the compositor");
        }
    }
}

/// **A window manager written for river tiles the desktop.** It binds the
/// globals, hears of each window and the output, proposes a column each in
/// its manage sequence and positions them in its render sequence; the
/// compositor puts each window there, drawn from then on, and gives the
/// keyboard to the window it focused.
#[test]
fn a_river_window_manager_tiles_the_windows_it_is_told_of() {
    let mut display = Display::<Solium>::new().expect("creating a test wayland display");
    let mut state = Solium::new(display.handle());
    let output = one_screen(&mut state);
    let screen = state
        .space
        .output_geometry(&output)
        .expect("the monitor is mapped");
    state.start_scripts(Some(Scripts::river_here().expect("the river bridge")));

    let mut river = connect_river(&mut display, &mut state);
    settle(&mut display, &mut state, &mut river);
    assert!(!river.wm.unavailable, "the window manager is the one bound");
    assert_eq!(
        river.wm.output,
        Some((screen.loc.x, screen.loc.y, screen.size.w, screen.size.h)),
        "it was told the output"
    );
    assert!(river.wm.manages >= 1 && river.wm.renders >= 1);

    let (conn, mut event_queue, mut client) = connect(&mut display, &mut state);
    let qh = event_queue.handle();
    let (first, first_toplevel, first_surface) =
        open_surface(&mut display, &mut state, &conn, &client, &qh);
    let (second, _second) = open_window(&mut display, &mut state, &conn, &client, &qh);
    settle(&mut display, &mut state, &mut river);

    assert_eq!(river.wm.tiles.len(), 2, "it was told both windows");
    let half = screen.size.w / 2;
    for (window, column) in [(&first, 0), (&second, 1)] {
        let id = state.panes.id_of(window).expect("a pane");
        let pane = state.panes.get(id).expect("the pane");
        assert_eq!(
            pane.slot(),
            Rectangle::new(
                (screen.loc.x + half * column, screen.loc.y).into(),
                (half, screen.size.h).into()
            ),
            "window {column} is in its column"
        );
    }
    assert_eq!(
        river
            .wm
            .tiles
            .iter()
            .map(|tile| tile.size)
            .collect::<Vec<_>>(),
        [Some((half, screen.size.h)); 2],
        "and was told the size it was given"
    );
    assert_eq!(
        state.focused_window().as_ref(),
        Some(&second),
        "the keyboard is the last window's, as the window manager asked"
    );
    // Hidden as it opened, drawn once it was placed: no present holds it.
    for window in [&first, &second] {
        let id = state.panes.id_of(window).expect("a pane");
        assert!(
            !crate::present::presented(state.panes.get(id).expect("the pane")),
            "a placed window is drawn"
        );
    }

    // Its key binding is the window manager's, and reaches it, followed by
    // a manage sequence, which is where a river window manager acts on it.
    let manages = river.wm.manages;
    assert!(state.trigger("super+t"), "super+t is bound");
    settle(&mut display, &mut state, &mut river);
    assert_eq!(river.wm.pressed, 1, "the window manager heard its key");
    assert!(
        river.wm.manages > manages,
        "and a manage sequence followed it"
    );

    // It closes the first window: the client is asked, and goes; the window
    // manager is told, and gives the rest of the output to the second.
    river.wm.close_first = true;
    river.wm.manage_dirty();
    settle(&mut display, &mut state, &mut river);
    // The compositor asks once the window has faded out.
    state.settle_closing(state.clock.now() + std::time::Duration::from_secs(5));
    pump(
        &mut display,
        &mut state,
        &conn,
        &qh,
        &mut event_queue,
        &mut client,
    );
    assert_eq!(
        client.closes,
        [wayland_client::Proxy::id(&first_toplevel)],
        "the client was asked to close the window the window manager closed"
    );
    first_toplevel.destroy();
    first_surface.destroy();
    pump(
        &mut display,
        &mut state,
        &conn,
        &qh,
        &mut event_queue,
        &mut client,
    );
    settle(&mut display, &mut state, &mut river);
    assert_eq!(
        river.wm.tiles.iter().filter(|tile| !tile.closed).count(),
        1,
        "it was told the first window closed"
    );
    let id = state.panes.id_of(&second).expect("a pane");
    assert_eq!(
        state.panes.get(id).map(Pane::slot),
        Some(screen),
        "and the second window has the output"
    );
}

/// **A window may keep a size of its own**: a window manager that proposes
/// none (0 by 0, as river allows) is told the size the window drew, once it
/// has drawn, and the window is placed where the window manager put it at
/// that size, as a stacking window manager places windows.
#[test]
fn a_river_window_manager_can_leave_a_window_its_own_size() {
    let mut display = Display::<Solium>::new().expect("creating a test wayland display");
    let mut state = Solium::new(display.handle());
    let output = one_screen(&mut state);
    let screen = state
        .space
        .output_geometry(&output)
        .expect("the monitor is mapped");
    state.start_scripts(Some(Scripts::river_here().expect("the river bridge")));
    let mut river = connect_river(&mut display, &mut state);
    river.wm.free = true;
    settle(&mut display, &mut state, &mut river);

    let (conn, event_queue, client) = connect(&mut display, &mut state);
    let qh = event_queue.handle();
    let (window, _toplevel) = open_window(&mut display, &mut state, &conn, &client, &qh);
    let own = window.geometry().size;
    settle(&mut display, &mut state, &mut river);

    assert_eq!(
        river.wm.tiles.first().and_then(|tile| tile.size),
        Some((own.w, own.h)),
        "it was told the size the window drew"
    );
    let id = state.panes.id_of(&window).expect("a pane");
    assert_eq!(
        state.panes.get(id).map(Pane::slot),
        Some(Rectangle::new(
            (screen.loc.x + 100, screen.loc.y + 50).into(),
            own
        )),
        "and it is where the window manager put it, at that size"
    );
    assert!(!crate::present::presented(
        state.panes.get(id).expect("the pane")
    ));
}

/// **A window placed before its first frame opens where it was placed.** A
/// terminal that takes a while to draw (foot started through podman, as
/// `dev/foot` starts it) is told of, managed and placed by the river window
/// manager before it has drawn anything; when it draws, it opens. Answered
/// with no place, its opening put it where the compositor puts a window
/// nobody placed, centred at its own size, and the window manager, having
/// changed nothing, never placed it again: rrwm's first terminal sat in the
/// middle of the screen at the size of the whole of it.
#[test]
fn a_window_placed_before_its_first_frame_opens_where_it_was_placed() {
    let mut display = Display::<Solium>::new().expect("creating a test wayland display");
    let mut state = Solium::new(display.handle());
    let output = one_screen(&mut state);
    let screen = state
        .space
        .output_geometry(&output)
        .expect("the monitor is mapped");
    state.start_scripts(Some(Scripts::river_here().expect("the river bridge")));
    let mut river = connect_river(&mut display, &mut state);
    settle(&mut display, &mut state, &mut river);

    let (conn, mut event_queue, mut client) = connect(&mut display, &mut state);
    let qh = event_queue.handle();
    let compositor = client.compositor.clone().expect("wl_compositor bound");
    let wm_base = client.wm_base.clone().expect("xdg_wm_base bound");
    let before: Vec<Window> = state.space.elements().cloned().collect();
    let surface = compositor.create_surface(&qh, ());
    let xdg_surface = wm_base.get_xdg_surface(&surface, &qh, ());
    let toplevel = xdg_surface.get_toplevel(&qh, ());
    client.leave_frame(&toplevel, &qh);
    // Named before it draws, as foot names its window: a name is what tells
    // the window manager of a window that has not drawn yet.
    toplevel.set_title("foot".to_owned());
    toplevel.set_app_id("foot".to_owned());
    surface.commit();
    pump(
        &mut display,
        &mut state,
        &conn,
        &qh,
        &mut event_queue,
        &mut client,
    );
    settle(&mut display, &mut state, &mut river);
    assert_eq!(
        river.wm.tiles.len(),
        1,
        "the premise: the window manager was told of the window before it drew"
    );
    let early: Vec<_> = state
        .panes
        .iter()
        .map(|pane| (pane.slot(), pane.placed(), pane.client().is_some()))
        .collect();
    assert!(
        early.iter().any(|(_, placed, _)| *placed == Some(screen)),
        "the premise: it was placed before it drew: {early:?}"
    );

    commit_buffer(&client, &qh, &surface, 64, 64);
    pump(
        &mut display,
        &mut state,
        &conn,
        &qh,
        &mut event_queue,
        &mut client,
    );
    settle(&mut display, &mut state, &mut river);
    let window = state
        .space
        .elements()
        .find(|window| !before.contains(window))
        .cloned()
        .expect("the window is on the desktop");
    // Where the space has it, which is where it is drawn and where it stays
    // once its application has had long enough to answer.
    assert_eq!(
        state.space.element_location(&window),
        Some(screen.loc),
        "it opened somewhere other than where the window manager put it"
    );
}

/// **Only the window manager `wm.toml` started is answered**: a second
/// client that binds the global, while one is bound, is told it is
/// unavailable.
#[test]
fn a_second_river_window_manager_is_told_it_is_unavailable() {
    let mut display = Display::<Solium>::new().expect("creating a test wayland display");
    let mut state = Solium::new(display.handle());
    let _output = one_screen(&mut state);
    state.start_scripts(Some(Scripts::river_here().expect("the river bridge")));

    let mut first = connect_river(&mut display, &mut state);
    settle(&mut display, &mut state, &mut first);
    let mut second = connect_river(&mut display, &mut state);
    settle(&mut display, &mut state, &mut second);
    assert!(!first.wm.unavailable);
    assert!(second.wm.unavailable, "only one window manager at a time");
}
